CREATE PERFETTO TABLE win26_win AS SELECT min(ts) lo,max(device_end) hi FROM win26_mb;
CREATE PERFETTO TABLE win26_events AS
SELECT d.*,MAX(d.ts,w.lo) b,MIN(d.ts+d.dur,w.hi) e FROM win26_dev d JOIN win26_win w ON d.ts<w.hi AND d.ts+d.dur>w.lo;
CREATE PERFETTO TABLE win26_phase AS
WITH x AS (SELECT m.*,(SELECT min(d.ts) FROM win26_dev d WHERE d.stream=7 AND d.host_ts>=m.bwd_cpu_start AND d.host_ts<m.cpu_end) bwd_gpu_start FROM win26_mb m)
SELECT mb,'forward' phase,ts b,bwd_gpu_start e FROM x
UNION ALL SELECT mb,'backward_including_recompute',bwd_gpu_start,device_end FROM x
UNION ALL SELECT mb,'between_microbatches',device_end,lead(ts) OVER(ORDER BY ts) FROM x;
CREATE PERFETTO TABLE win26_union AS
WITH x AS(
SELECT id,kind,b,e FROM win26_events
UNION ALL SELECT id,'all_device',b,e FROM win26_events
UNION ALL SELECT id,'main_stream',b,e FROM win26_events WHERE stream=7),
y AS(SELECT *,MAX(e) OVER(PARTITION BY kind ORDER BY b,e,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prev_end FROM x)
SELECT kind,count(*) n,sum(e-b)/1e6 sum_ms,sum(MAX(0,e-MAX(b,coalesce(prev_end,b))))/1e6 union_ms FROM y GROUP BY kind;
SELECT * FROM win26_union;

SELECT name,count(*) n,sum(dur)/1e6 sum_ms,max(dur)/1e6 max_ms FROM thread_slice
WHERE category IN ('cuda_runtime','cuda_driver') AND ts>=(SELECT lo FROM win26_win) AND ts<(SELECT hi FROM win26_win)
GROUP BY name ORDER BY sum(dur) DESC LIMIT 12;
